import assert from "node:assert/strict";
import { test } from "vitest";
import { sha256 } from "../src/canonical-json.js";
import { verifyGeometryRegistrationV1, type GeometryRegistrationV1VerificationInput } from
  "../src/geometry-registration-v1.js";

// Generated by Python geometry_registration_v1.validate_geometry_registration_v1
// from services/worker/tests/test_geometry_registration_v1.py::packet, then
// source SHA substituted with SHA of the synthetic bytes below.
const pythonFixture = JSON.parse(`{"packet":{"schemaVersion":"geometry-registration-v1","source":{"sourceSha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","pdfPageNumber":1},"pageFrame":{"coordinateSpace":"CANONICAL_VISIBLE_NORMALIZED","width":1.0,"height":1.0,"rotate":0,"renderSha256":null},"targetFrame":{"kind":"LOCAL_2D","frameId":"SYNTHETIC-SITE-GRID","unit":"m","xAxis":"RIGHT","yAxis":"UP","minScale":0.01,"maxScale":0.1},"controlPoints":[{"id":"P0","evidenceRef":"manual-point-0","page":[0.1,0.1],"project":[100.00273205080757,199.99926794919244]},{"id":"P1","evidenceRef":"manual-point-1","page":[0.8,0.1],"project":[100.01485640646055,200.00626794919242]},{"id":"P2","evidenceRef":"manual-point-2","page":[0.1,0.8],"project":[100.00973205080757,199.98714359353946]},{"id":"P3","evidenceRef":"manual-point-3","page":[0.8,0.8],"project":[100.02185640646056,199.99414359353946]},{"id":"P4","evidenceRef":"manual-point-4","page":[0.45,0.55],"project":[100.01329422863407,199.99497372055836]}],"trainingPointIds":["P0","P1","P2"],"maxHoldoutResidualProjectUnits":1e-08,"queryPoints":[[0.4,0.4]]},"result":{"schemaVersion":"geometry-registration-v1","status":"REVIEW_ONLY","reasonCode":"AUTHENTICATED_REGISTRATION_PENDING","source":{"sourceSha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","pdfPageNumber":1},"pageFrame":{"coordinateSpace":"CANONICAL_VISIBLE_NORMALIZED","width":1.0,"height":1.0,"rotate":0,"renderSha256":null},"targetFrame":{"kind":"LOCAL_2D","frameId":"SYNTHETIC-SITE-GRID","unit":"m","xAxis":"RIGHT","yAxis":"UP","minScale":0.01,"maxScale":0.1},"trainingPointIds":["P0","P1","P2"],"holdouts":[{"id":"P3","evidenceRef":"manual-point-3","residualProjectUnits":5.859285502108464e-14},{"id":"P4","evidenceRef":"manual-point-4","residualProjectUnits":1.4210854715202004e-14}],"maxHoldoutResidualProjectUnits":5.859285502108464e-14,"holdoutToleranceProjectUnits":1e-08,"maxRoundtripPageUnits":1.933610170585088e-12,"forwardMatrix":[0.017320508075694564,0.010000000000007146,99.99999999999999,0.009999999999966543,-0.017320508075694564,200.0],"inverseMatrix":[43.301270189243176,25.000000000021767,-9330.12701892867,24.999999999920263,-43.301270189243176,6160.254037856608],"determinant":-0.0003999999999999375,"scaleRangeProjectUnitsPerPageUnit":[0.019999999999998436,0.01999999999999844],"calibrationDomainPage":[[0.1,0.1],[0.8,0.1],[0.8,0.8],[0.1,0.8]],"queryPoints":[{"page":[0.4,0.4],"project":[100.01092820323026,199.99707179676972]}],"facts":[]}}`);

function fixture(): GeometryRegistrationV1VerificationInput {
  const sourceBytes = Buffer.from("%PDF-1.4\n1 0 obj\n<< /Type /Page >>\nendobj\n%%EOF\n");
  const expectedSourceSha256 = sha256(sourceBytes);
  const packet = structuredClone(pythonFixture.packet);
  const result = structuredClone(pythonFixture.result);
  packet.source.sourceSha256 = expectedSourceSha256;
  result.source.sourceSha256 = expectedSourceSha256;
  return { packet, result, sourceBytes, expectedSourceSha256,
    trusted: { source: structuredClone(packet.source), pageFrame: structuredClone(packet.pageFrame),
      targetFrame: structuredClone(packet.targetFrame), controlPoints: structuredClone(packet.controlPoints),
      trainingPointIds: structuredClone(packet.trainingPointIds),
      maxHoldoutResidualProjectUnits: packet.maxHoldoutResidualProjectUnits,
      queryPoints: structuredClone(packet.queryPoints) } };
}

test("Python fixture passes independent TS affine, holdout, inverse, hull replay", () => {
  const input = fixture();
  assert.equal(verifyGeometryRegistrationV1(input), true);
  assert.equal((input.result as any).status, "REVIEW_ONLY");
  assert.deepEqual((input.result as any).facts, []);
});

test("rejects mutated output, including added positive facts", () => {
  const changes: Array<(result: any) => void> = [
    (result) => { result.status = "APPROVED"; },
    (result) => { result.facts.push({ kind: "BOUNDARY" }); },
    (result) => { result.forwardMatrix[0] += 0.001; },
    (result) => { result.inverseMatrix[2] += 0.01; },
    (result) => { result.holdouts[0].residualProjectUnits += 0.001; },
    (result) => { result.calibrationDomainPage[0][0] += 0.01; },
    (result) => { result.queryPoints[0].project[0] += 0.01; },
    (result) => { result.worldCrs = "EPSG:3857"; },
  ];
  for (const change of changes) {
    const input = fixture();
    change(input.result);
    assert.equal(verifyGeometryRegistrationV1(input), false);
  }
});

test("rejects source and independently pinned decisions, even self-consistent edits", () => {
  const changedBytes = fixture();
  changedBytes.sourceBytes[15] ^= 1;
  assert.equal(verifyGeometryRegistrationV1(changedBytes), false);
  const changes: Array<(packet: any) => void> = [
    (packet) => { packet.source.pdfPageNumber = 2; },
    (packet) => { packet.pageFrame.rotate = 90; },
    (packet) => { packet.targetFrame.frameId = "OTHER-GRID"; },
    (packet) => { packet.controlPoints[3].project[0] += 0.1; },
    (packet) => { packet.trainingPointIds = ["P0", "P1", "P4"]; },
    (packet) => { packet.maxHoldoutResidualProjectUnits = 1000; },
    (packet) => { packet.queryPoints = [[0.5, 0.5]]; },
  ];
  for (const change of changes) {
    const input = fixture();
    change(input.packet);
    assert.equal(verifyGeometryRegistrationV1(input), false);
  }
});

test("missing trust, tolerance, mirror and out-of-hull query fail closed", () => {
  const missingTrust = fixture();
  delete (missingTrust as any).trusted;
  assert.equal(verifyGeometryRegistrationV1(missingTrust), false);
  const noTolerance = fixture();
  delete (noTolerance.packet as any).maxHoldoutResidualProjectUnits;
  delete (noTolerance.trusted as any).maxHoldoutResidualProjectUnits;
  assert.equal(verifyGeometryRegistrationV1(noTolerance), false);
  const mirrored = fixture();
  (mirrored.packet as any).targetFrame.yAxis = "DOWN";
  (mirrored.trusted.targetFrame as any).yAxis = "DOWN";
  assert.equal(verifyGeometryRegistrationV1(mirrored), false);
  const outside = fixture();
  (outside.packet as any).queryPoints = [[0.95, 0.95]];
  outside.trusted.queryPoints = [[0.95, 0.95]];
  assert.equal(verifyGeometryRegistrationV1(outside), false);
});

test("raster requires independent render SHA and exact PNG dimensions", () => {
  const input = fixture();
  const png = Buffer.alloc(45);
  Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]).copy(png, 0);
  png.write("IHDR", 12, "ascii");
  png.writeUInt32BE(800, 16);
  png.writeUInt32BE(600, 20);
  const digest = sha256(png);
  (input.packet as any).pageFrame = { coordinateSpace: "RASTER_PIXEL", width: 800,
    height: 600, rotate: 90, renderSha256: digest };
  for (const point of (input.packet as any).controlPoints) {
    point.page[0] *= 800;
    point.page[1] *= 600;
  }
  (input.packet as any).queryPoints = [[320, 240]];
  (input.packet as any).targetFrame.minScale = 0.00001;
  (input.packet as any).targetFrame.maxScale = 0.001;
  (input.result as any).pageFrame = structuredClone((input.packet as any).pageFrame);
  (input.result as any).targetFrame = structuredClone((input.packet as any).targetFrame);
  (input.result as any).maxRoundtripPageUnits = 1.041250292910165e-9;
  (input.result as any).forwardMatrix = [2.1650635094618203e-5, 1.6666666666678577e-5,
    99.99999999999999, 1.2499999999958178e-5, -2.886751345949094e-5, 200];
  (input.result as any).inverseMatrix = [34641.01615139454, 20000.00000001742,
    -7464101.615142938, 14999.999999952157, -25980.762113545905, 3696152.4227139656];
  (input.result as any).determinant = -8.333333333332031e-10;
  (input.result as any).scaleRangeProjectUnitsPerPageUnit = [2.499999999998536e-5,
    3.333333333334764e-5];
  (input.result as any).calibrationDomainPage = [[80, 60], [640, 60], [640, 480], [80, 480]];
  (input.result as any).queryPoints[0].page = [320, 240];
  input.trusted.pageFrame = structuredClone((input.packet as any).pageFrame);
  input.trusted.targetFrame = structuredClone((input.packet as any).targetFrame);
  input.trusted.controlPoints = structuredClone((input.packet as any).controlPoints);
  input.trusted.queryPoints = structuredClone((input.packet as any).queryPoints);
  input.renderBytes = png;
  assert.equal(verifyGeometryRegistrationV1(input), false);
  input.expectedRenderSha256 = digest;
  assert.equal(verifyGeometryRegistrationV1(input), true);
  input.expectedRenderSha256 = "c".repeat(64);
  assert.equal(verifyGeometryRegistrationV1(input), false);
  input.expectedRenderSha256 = digest;
  png.writeUInt32BE(799, 16);
  assert.equal(verifyGeometryRegistrationV1(input), false);
});
